define({"topics":[{"title":"Installing software on a new system (USB load only)","shortdesc":"<p class=\"shortdesc\">Install the host system software on a new system (USB load only).<\/p>","href":"r_InstallingSoftwareOnANewSystem.html","attributes":{"data-id":"id_2038386"},"menu":{"hasChildren":false},"tocID":"id_2038386-d46e35846","topics":[]},{"title":"Upgrading software on an existing system (USB load only)","shortdesc":"<p class=\"shortdesc\">This procedure addresses upgrading software via a USB download, as well as the common steps following those procedures. Please read instructions carefully.<\/p>","href":"r_UpgradingSoftwareOnAnExistingSystem.html","attributes":{"data-id":"id_2038388"},"menu":{"hasChildren":false},"tocID":"id_2038388-d46e35950","topics":[]},{"title":"Reloading software for system recovery from forgotten passwords","shortdesc":"<p class=\"shortdesc\">Reload the host system software for <span class=\"ph\">PX29.1<\/span><span class=\"ph\">software version 30<\/span> and later (USB load only) if you want to reset your passwords.<\/p>","href":"r_ReloadingSoftwareForASystemRecoveryFromForgottenPassword.html","attributes":{"data-id":"id_2028927"},"menu":{"hasChildren":false},"tocID":"id_2028927-d46e36054","topics":[]}]});